//! Shared-memory ring and message protocol between maki and external
//! consumers (e.g. haunt), generated by blitgen-zig.
//!
//! Everything under `schema` is generated from [`schema/maki_shmem.blit`];
//! regenerate with:
//!
//! ```sh
//! blitgen-zig hash --write schema/maki_shmem.blit
//! blitgen-zig blit schema/maki_shmem.blit --target rust --out-dir src/generated
//! ```
//!
//! The ring is [`ring::Ring`] over `Ring512x2048`: 2048 slots of 512 bytes,
//! one producer and up to 32 registered readers, mapped from
//! `ring::ring_path(pid)`. Messages are the records carrying a `MSG_ID`
//! (`Hello`, `ChatLine`, `Chunk`, `Status`, `MakiStatus`); a record with none
//! (`RingSlotHeader`, `RingControl`, `RingConsumerSlot`, `RingHeader`, the
//! ring compositions) is layout-only and never framed.
//!
//! [`MakiStatus`] is the maki client's periodic broadcast: `session_id` +
//! `session_title` identify the session, `pid` the process, `state` says
//! whether it is working (1), idle (2), or waiting on input (3) — 0 is
//! unknown — `context_used`/`context_limit` the context window in tokens,
//! `cost_usd` the running cost, and `last_tool` the most recent tool call.

// Generated code: the generator's output shape, not reviewable choices.
#[allow(
    clippy::manual_slice_size_calculation,
    clippy::match_single_binding,
    clippy::manual_is_multiple_of
)]
#[path = "generated/generated_schema.rs"]
pub mod schema;

pub mod ring;

pub mod broadcast;

pub use broadcast::Speaker;

pub mod control;

pub mod auth;

pub mod payload;

pub use schema::{
    BLIT_BINDING_SHA256_PREFIX, BLIT_LAYOUT_SHA256, BLIT_SCHEMA_ID, BLIT_SCHEMA_VERSION, BlitRecord,
    ChatLine, Chunk, Hello, MakiAck, MakiCommand, MakiStatus, MsgId, Ring512x2048, RingConsumerSlot,
    RingControl, RingHeader, RingSlot512, RingSlotHeader, Status,
};

/// Fixed-buffer utf8 helpers for the schema's `utf8.fixed` fields.
pub mod text {
    /// Copies `s` into `dest`, NUL-padded and truncated on a char boundary.
    pub fn encode(dest: &mut [u8], s: &str) {
        dest.fill(0);
        let limit = dest.len().min(s.len());
        let mut end = limit;
        while end > 0 && !s.is_char_boundary(end) {
            end -= 1;
        }
        dest[..end].copy_from_slice(&s.as_bytes()[..end]);
    }

    /// The utf8 text of a fixed field, up to the first NUL.
    pub fn decode(bytes: &[u8]) -> std::borrow::Cow<'_, str> {
        let end = bytes.iter().position(|b| *b == 0).unwrap_or(bytes.len());
        String::from_utf8_lossy(&bytes[..end])
    }

    #[cfg(test)]
    mod tests {
        use super::*;

        #[test]
        fn encode_truncates_on_char_boundary() {
            let mut buf = [0u8; 4];
            encode(&mut buf, "ab\u{20ac}c");
            assert_eq!(&buf, b"ab\0\0");
            let mut buf = [0u8; 8];
            encode(&mut buf, "ab");
            assert_eq!(&buf, b"ab\0\0\0\0\0\0");
        }

        #[test]
        fn decode_stops_at_nul() {
            assert_eq!(decode(b"ab\0\0\0"), "ab");
            assert_eq!(decode(b"ab"), "ab");
        }
    }
}
